PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS p_organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_users(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, name TEXT NOT NULL, email TEXT NOT NULL, password_hash TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, avatar TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '{}', UNIQUE(org_id,email));
CREATE TABLE IF NOT EXISTS p_roles(user_id TEXT NOT NULL REFERENCES p_users ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('admin','coach','student')), PRIMARY KEY(user_id,role));
CREATE TABLE IF NOT EXISTS p_coaches(id TEXT PRIMARY KEY REFERENCES p_users ON DELETE CASCADE, bio TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p_students(id TEXT PRIMARY KEY REFERENCES p_users ON DELETE CASCADE, born TEXT NOT NULL DEFAULT '', goal TEXT NOT NULL DEFAULT '', height_cm REAL, weight_kg REAL, scenario TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p_sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES p_users ON DELETE CASCADE, role TEXT NOT NULL, expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS p_locations(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', capacity INTEGER NOT NULL DEFAULT 12 CHECK(capacity>0), detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_rooms(id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES p_locations ON DELETE CASCADE, name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS p_coach_locations(coach_id TEXT NOT NULL REFERENCES p_coaches ON DELETE CASCADE, location_id TEXT NOT NULL REFERENCES p_locations ON DELETE CASCADE, PRIMARY KEY(coach_id,location_id));
CREATE TABLE IF NOT EXISTS p_student_locations(student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, location_id TEXT NOT NULL REFERENCES p_locations ON DELETE CASCADE, PRIMARY KEY(student_id,location_id));
CREATE TABLE IF NOT EXISTS p_coach_students(coach_id TEXT NOT NULL REFERENCES p_coaches ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, PRIMARY KEY(coach_id,student_id));
CREATE TABLE IF NOT EXISTS p_regions(id TEXT PRIMARY KEY, name TEXT NOT NULL, side TEXT NOT NULL, explanation TEXT NOT NULL, structures TEXT NOT NULL, landmark_ids TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_equipment(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, location_id TEXT NOT NULL REFERENCES p_locations ON DELETE CASCADE, name TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>=0), available INTEGER NOT NULL DEFAULT 1 CHECK(available>=0 AND available<=quantity), detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_exercises(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, owner_id TEXT REFERENCES p_users ON DELETE SET NULL, name TEXT NOT NULL, category TEXT NOT NULL, difficulty TEXT NOT NULL DEFAULT 'Foundation', region_id TEXT REFERENCES p_regions ON DELETE SET NULL, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','organization')), detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_exercise_equipment(exercise_id TEXT NOT NULL REFERENCES p_exercises ON DELETE CASCADE, equipment_id TEXT NOT NULL REFERENCES p_equipment ON DELETE CASCADE, quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0), PRIMARY KEY(exercise_id,equipment_id));
CREATE TABLE IF NOT EXISTS p_media(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, owner_id TEXT REFERENCES p_users ON DELETE SET NULL, student_id TEXT REFERENCES p_students ON DELETE CASCADE, exercise_id TEXT REFERENCES p_exercises ON DELETE CASCADE, kind TEXT NOT NULL, mime TEXT NOT NULL, filename TEXT NOT NULL, path TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_exercise_media(exercise_id TEXT NOT NULL REFERENCES p_exercises ON DELETE CASCADE, media_id TEXT NOT NULL REFERENCES p_media ON DELETE CASCADE, PRIMARY KEY(exercise_id,media_id));
CREATE TABLE IF NOT EXISTS p_resources(id TEXT PRIMARY KEY, exercise_id TEXT NOT NULL REFERENCES p_exercises ON DELETE CASCADE, title TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_programs(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, owner_id TEXT REFERENCES p_users ON DELETE SET NULL, location_id TEXT REFERENCES p_locations ON DELETE SET NULL, name TEXT NOT NULL, goal TEXT NOT NULL DEFAULT '', region_id TEXT REFERENCES p_regions ON DELETE SET NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_program_exercises(id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES p_programs ON DELETE CASCADE, exercise_id TEXT NOT NULL REFERENCES p_exercises ON DELETE RESTRICT, position INTEGER NOT NULL, phase TEXT NOT NULL DEFAULT 'Practice', sets INTEGER NOT NULL DEFAULT 1 CHECK(sets>0), reps INTEGER NOT NULL DEFAULT 8 CHECK(reps>=0), seconds INTEGER NOT NULL DEFAULT 60 CHECK(seconds>=0), rest INTEGER NOT NULL DEFAULT 20 CHECK(rest>=0), notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p_analyses(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, coach_id TEXT REFERENCES p_users ON DELETE SET NULL, location_id TEXT REFERENCES p_locations ON DELETE SET NULL, kind TEXT NOT NULL, protocol TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0, result TEXT NOT NULL DEFAULT '{}', detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_program_assignments(id TEXT PRIMARY KEY, program_id TEXT NOT NULL REFERENCES p_programs ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, analysis_id TEXT REFERENCES p_analyses ON DELETE SET NULL, starts_on TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p_reservations(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, coach_id TEXT REFERENCES p_coaches ON DELETE SET NULL, location_id TEXT REFERENCES p_locations ON DELETE SET NULL, room_id TEXT REFERENCES p_rooms ON DELETE SET NULL, program_id TEXT REFERENCES p_programs ON DELETE SET NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'reserved', session_type TEXT NOT NULL DEFAULT 'Individual practice', detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_training_sessions(id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, reservation_id TEXT REFERENCES p_reservations ON DELETE SET NULL, program_id TEXT REFERENCES p_programs ON DELETE SET NULL, analysis_id TEXT REFERENCES p_analyses ON DELETE SET NULL, performed_at TEXT NOT NULL, completed TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS p_image_analyses(id TEXT PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, media_id TEXT REFERENCES p_media ON DELETE SET NULL, view TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_video_analyses(id TEXT PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, media_id TEXT REFERENCES p_media ON DELETE SET NULL, view TEXT NOT NULL, duration REAL NOT NULL, result TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_pose_frames(id TEXT PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, person_id TEXT NOT NULL, view TEXT NOT NULL, frame_index INTEGER NOT NULL, time REAL NOT NULL, suitable INTEGER NOT NULL, UNIQUE(analysis_id,person_id,view,frame_index));
CREATE TABLE IF NOT EXISTS p_landmarks(id TEXT PRIMARY KEY, name TEXT NOT NULL, region_id TEXT REFERENCES p_regions, method TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_coordinates(id INTEGER PRIMARY KEY, frame_id TEXT NOT NULL REFERENCES p_pose_frames ON DELETE CASCADE, landmark_id TEXT NOT NULL REFERENCES p_landmarks, x REAL, y REAL, z REAL, confidence REAL, space TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', UNIQUE(frame_id,landmark_id,space));
CREATE TABLE IF NOT EXISTS p_joint_measurements(id INTEGER PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, person_id TEXT NOT NULL, view TEXT NOT NULL, name TEXT NOT NULL, value REAL, unit TEXT NOT NULL, confidence REAL, status TEXT NOT NULL, region_id TEXT REFERENCES p_regions, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_posture_measurements(id INTEGER PRIMARY KEY, measurement_id INTEGER NOT NULL REFERENCES p_joint_measurements ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS p_symmetry_measurements(id INTEGER PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, region_id TEXT REFERENCES p_regions, name TEXT NOT NULL, value REAL, unit TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_movement_analyses(id TEXT PRIMARY KEY, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, person_id TEXT NOT NULL, summary TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_rom_measurements(id INTEGER PRIMARY KEY, movement_id TEXT NOT NULL REFERENCES p_movement_analyses ON DELETE CASCADE, name TEXT NOT NULL, value REAL, unit TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_scans(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, analysis_id TEXT REFERENCES p_analyses ON DELETE SET NULL, region_id TEXT REFERENCES p_regions, media_id TEXT NOT NULL REFERENCES p_media ON DELETE CASCADE, name TEXT NOT NULL, scan_type TEXT NOT NULL, captured_at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_scan_findings(id TEXT PRIMARY KEY, scan_id TEXT NOT NULL REFERENCES p_scans ON DELETE CASCADE, region_id TEXT REFERENCES p_regions, x REAL NOT NULL, y REAL NOT NULL, x2 REAL, y2 REAL, frame_index INTEGER NOT NULL DEFAULT 0, text TEXT NOT NULL, author_id TEXT REFERENCES p_users ON DELETE SET NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_observations(id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, analysis_id TEXT REFERENCES p_analyses ON DELETE CASCADE, region_id TEXT REFERENCES p_regions, scan_id TEXT REFERENCES p_scans ON DELETE SET NULL, kind TEXT NOT NULL, text TEXT NOT NULL, source TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS p_notes(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, author_id TEXT REFERENCES p_users ON DELETE SET NULL, analysis_id TEXT REFERENCES p_analyses ON DELETE SET NULL, region_id TEXT REFERENCES p_regions, scan_id TEXT REFERENCES p_scans ON DELETE SET NULL, program_id TEXT REFERENCES p_programs ON DELETE SET NULL, exercise_id TEXT REFERENCES p_exercises ON DELETE SET NULL, text TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'student' CHECK(visibility IN ('student','coach')), created_at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_progress_records(id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, analysis_id TEXT NOT NULL REFERENCES p_analyses ON DELETE CASCADE, metric TEXT NOT NULL, value REAL, unit TEXT NOT NULL, recorded_at TEXT NOT NULL, demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS p_jobs(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES p_students ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES p_users ON DELETE CASCADE, analysis_id TEXT REFERENCES p_analyses ON DELETE SET NULL, state TEXT NOT NULL, progress TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, finished_at TEXT, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_audit(id INTEGER PRIMARY KEY, org_id TEXT NOT NULL REFERENCES p_organizations ON DELETE CASCADE, actor_id TEXT REFERENCES p_users ON DELETE SET NULL, action TEXT NOT NULL, subject_id TEXT NOT NULL, created_at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS p_schema(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS p_users_email ON p_users(email);
CREATE INDEX IF NOT EXISTS p_users_org ON p_users(org_id);
CREATE INDEX IF NOT EXISTS p_analyses_student ON p_analyses(student_id,created_at);
CREATE INDEX IF NOT EXISTS p_coordinates_frame ON p_coordinates(frame_id);
CREATE INDEX IF NOT EXISTS p_frames_analysis ON p_pose_frames(analysis_id,person_id,time);
CREATE INDEX IF NOT EXISTS p_exercises_search ON p_exercises(org_id,category,name);
CREATE INDEX IF NOT EXISTS p_programs_owner ON p_programs(org_id,owner_id);
CREATE INDEX IF NOT EXISTS p_assignments_student ON p_program_assignments(student_id,active);
CREATE INDEX IF NOT EXISTS p_reservations_time ON p_reservations(org_id,starts_at,coach_id);
CREATE INDEX IF NOT EXISTS p_notes_student ON p_notes(student_id,region_id,created_at);
CREATE INDEX IF NOT EXISTS p_media_student ON p_media(student_id);
CREATE INDEX IF NOT EXISTS p_media_exercise ON p_media(exercise_id);
CREATE INDEX IF NOT EXISTS p_progress_student ON p_progress_records(student_id,metric,recorded_at);
